update public.rec_legend_catalog set legend_tier = 'immortal' where legend_tier is null;
alter table public.rec_legend_catalog alter column legend_tier set default 'legend';
alter table public.rec_legend_catalog alter column legend_tier set not null;
alter table public.rec_legend_catalog drop constraint if exists rec_legend_catalog_legend_tier_check;
alter table public.rec_legend_catalog add constraint rec_legend_catalog_legend_tier_check check (legend_tier in ('legend','immortal'));
alter table public.rec_legend_catalog drop constraint if exists rec_legend_catalog_name_position_game_scope_key;
alter table public.rec_legend_catalog drop constraint if exists rec_legend_catalog_name_position_key;
delete from public.rec_legend_catalog;
